test("CLI help, version and print-command bypass runtime settings and preserve their output channels", (t) => {
  const { root, file, run } = setup(t);
  fs.mkdirSync(path.dirname(file), { mode: 0o700 });
  fs.writeFileSync(file, "{ malformed", { mode: 0o600 });
  for (const target of Object.keys(targets)) {
    const result = run(target, ["--help"]);
    assert.equal(result.status, 0);
    assert.match(result.stdout + result.stderr, /usage:/);
    assert.doesNotMatch(result.stdout + result.stderr, /process=|configuration rejected/);
  }
  const stm = run("stm", ["--version"]);
  assert.equal(stm.status, 1); // Preserve the existing stm version return code.
  assert.equal(stm.stdout, "");
  assert.equal(stm.stderr, "0.0\n");
  const projector = run("projector", ["--version"]);
  assert.equal(projector.status, 0);
  assert.equal(projector.stdout, "stm_projector 0.1\n");
  assert.equal(projector.stderr, "");
  const capture = run("capture", ["--program", "/mock/dumpcap", "--interfaces", "lo", "--no-auto-interfaces",
    "--output", path.join(root, "capture", "cap.pcapng"), "--print-command"]);
  assert.equal(capture.status, 0);
  assert.match(capture.stdout, /^'\/mock\/dumpcap' .*'-i' 'lo'/);
  assert.equal(capture.stderr, "");
  assert.equal(fs.readFileSync(file, "utf8"), "{ malformed");
});

