// Package the license documents belonging to the dependencies actually installed
// for both applications. Keep the original text; publish it as text/plain.
const fs = require('node:fs');
const path = require('node:path');
const { createHash } = require('node:crypto');

function packageLicenses(root) {
  const destination = path.join(root, 'fe/external-pages/licenses');
  fs.mkdirSync(destination, { recursive: true });
  const records = new Map();
  const publish = (id, name, contents) => {
    const file = createHash('sha256').update(id).digest('hex').slice(0, 24) + '.txt';
    fs.writeFileSync(path.join(destination, file), contents);
    records.set(id, { id, name, url: '/external-pages/licenses/' + file });
  };
  const release = JSON.parse(fs.readFileSync(path.join(root, 'conf/information.release.json'), 'utf8'));
  for (const source of release.license_sources ?? []) {
    const file = path.resolve(root, source.path);
    if (source.optional && !fs.existsSync(file)) continue;
    publish(source.id, source.name, fs.readFileSync(file));
  }
  const visited = new Set();
  function findPackage(name, from) {
    for (let directory = from; ; directory = path.dirname(directory)) {
      const file = path.join(directory, 'node_modules', name, 'package.json');
      if (fs.existsSync(file)) return path.dirname(file);
      if (directory === path.dirname(directory)) return null;
    }
  }
  function visit(directory) {
    directory = fs.realpathSync(directory);
    if (visited.has(directory)) return;
    visited.add(directory);
    const pkg = JSON.parse(fs.readFileSync(path.join(directory, 'package.json'), 'utf8'));
    const files = fs.readdirSync(directory).filter(file => /^(licen[cs]e|copying)(?:\..*)?$/i.test(file) && fs.statSync(path.join(directory, file)).isFile());
    if (files.length) {
      const id = 'npm:' + pkg.name.replace(/[^A-Za-z0-9_.:/-]/g, '_') + ':' + pkg.version.replace(/[^A-Za-z0-9_.-]/g, '_');
      publish(id, `${pkg.name} ${pkg.version}`, files.map(file => fs.readFileSync(path.join(directory, file), 'utf8')).join('\n\n'));
    }
    for (const name of Object.keys({ ...pkg.dependencies, ...pkg.optionalDependencies, ...pkg.peerDependencies })) {
      const dependency = findPackage(name, directory);
      if (dependency) visit(dependency);
    }
  }
  for (const workspace of ['server', 'client']) {
    const directory = path.join(root, 'fe', workspace);
    const pkg = JSON.parse(fs.readFileSync(path.join(directory, 'package.json'), 'utf8'));
    for (const name of Object.keys(pkg.dependencies ?? {})) {
      const dependency = findPackage(name, directory);
      if (dependency) visit(dependency);
    }
  }
  const manifest = [...records.values()].sort((a, b) => a.name.localeCompare(b.name, 'en'));
  fs.writeFileSync(path.join(destination, 'manifest.json'), JSON.stringify(manifest, null, 2) + '\n');
}

module.exports = { packageLicenses };

