const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const os = require('node:os');
const path = require('node:path');
const Fastify = require('fastify');
const { mergeInformation, registerInformation } = require('../server/dist/information');
const schema = require('../../conf/information.schema.json');
const product = { name: 'STM', manufacturer: '', version: '1.0', released_at: null, copyright: '' };
const program = { id: 'stm', name: 'stm', version: '0.0', commit: 'abc', built_at: null, status: 'ok' };
const base = () => ({ schema_version: 1, generated_at: null, source: 'supervisor.conf', product, programs: [program], licenses: [] });

test('manual fields survive generation; arrays merge by id with stable order, append and hide', () => {
  const input = base();
  const result = mergeInformation(input, { product: { manufacturer: 'Manufacturer' }, programs: [
    { id: 'stm', hidden: true }, { ...program, id: 'extra', name: 'Extra' }
  ], licenses: [{ id: 'license', name: 'License', url: '/external-pages/licenses/product.html' }] }, schema);
  assert.equal(result.product.manufacturer, 'Manufacturer');
  assert.equal(result.product.version, '1.0');
  assert.deepEqual(result.programs.map(item => item.id), ['extra']);
  assert.equal(input.programs.length, 1);
  assert.deepEqual(mergeInformation(input, { programs: [] }, schema).programs, input.programs);
  assert.deepEqual(mergeInformation({ ...input, programs: [] }, {}, schema).programs, []);
});

test('invalid definitions, unknown patch fields, duplicate ids and unsafe links fail visibly', () => {
  for (const patch of [
    { product: { version: 1 } }, { product: { typo: 'value' } }, { source: 'other' },
    { programs: [{ id: 'stm' }, { id: 'stm' }] }, { programs: [{ id: 'new' }] },
    { product: { released_at: '2026-11-02' } },
    { licenses: [{ id: 'x', name: 'x', url: 'javascript:alert(1)' }] },
    { licenses: [{ id: 'x', name: 'x', url: '//other-host/path' }] },
    { licenses: [{ id: 'x', name: 'x', url: '/\\other-host/path' }] }
  ]) assert.throws(() => mergeInformation(base(), patch, schema));
  for (const url of ['https://example.com/license', '/licenses/license.html'])
    assert.equal(mergeInformation(base(), { licenses: [{ id: 'x', name: 'x', url }] }, schema).licenses[0].url, url);
  assert.throws(() => mergeInformation({ ...base(), schema_version: 2 }, {}, schema));
});

test('GET reloads edits, reports invalid overrides, missing inventory and unreadable files without executing tools', async t => {
  const directory = await fs.mkdtemp(path.join(os.tmpdir(), 'stm-information-'));
  const app = Fastify();
  t.after(async () => { await app.close(); await fs.rm(directory, { recursive: true, force: true }); });
  const file = path.join(directory, 'generated.json'), override = path.join(directory, 'override.json');
  await registerInformation(app, { file, override, schema: path.resolve(__dirname, '../../conf/information.schema.json') });
  assert.equal((await app.inject('/api/information')).statusCode, 503);
  await fs.writeFile(file, JSON.stringify(base()));
  let response = await app.inject('/api/information');
  assert.equal(response.statusCode, 200);
  assert.equal(response.headers['cache-control'], 'no-store');
  await fs.writeFile(override, JSON.stringify({ product: { name: '<img src=x onerror=alert(1)>' } }));
  assert.equal((await app.inject('/api/information')).json().product.name, '<img src=x onerror=alert(1)>');
  await fs.writeFile(override, '{');
  response = await app.inject('/api/information');
  assert.equal(response.statusCode, 422);
  assert.match(response.json().error, /override/);
  await fs.unlink(override);
  await fs.writeFile(file, JSON.stringify({ ...base(), programs: [program, program] }));
  assert.equal((await app.inject('/api/information')).statusCode, 422);
  await fs.rm(file);
  await fs.mkdir(file);
  assert.equal((await app.inject('/api/information')).statusCode, 500);
});

