import { readFile } from "node:fs/promises";
import type { FastifyInstance } from "fastify";

type ObjectValue = Record<string, any>;

// Validate the small, checked-in schema subset without altering the input.
// In particular, unknown fields must be errors rather than silently removed.
export function validateDefinition(value: unknown, schema: ObjectValue, location = "information"): void {
  if (schema.anyOf) {
    if (schema.anyOf.some((choice: ObjectValue) => { try { validateDefinition(value, choice, location); return true; } catch { return false; } })) return;
    throw new Error(`${location}: expected a timezone-qualified date-time or null`);
  }
  if (schema.const !== undefined && value !== schema.const) throw new Error(`${location}: unsupported schema version`);
  if (schema.enum && !schema.enum.includes(value)) throw new Error(`${location}: unexpected value`);
  const type = value === null ? "null" : Array.isArray(value) ? "array" : typeof value;
  if (schema.type && !(Array.isArray(schema.type) ? schema.type : [schema.type]).includes(type)) throw new Error(`${location}: expected ${schema.type}`);
  if (typeof value === "string") {
    if (value.length > (schema.maxLength ?? Infinity) || value.length < (schema.minLength ?? 0)) throw new Error(`${location}: invalid length`);
    if (schema.pattern && !new RegExp(schema.pattern).test(value)) throw new Error(`${location}: invalid format`);
    if (schema.format === "date-time" && (!/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d+)?(?:Z|[+-]\d\d:\d\d)$/.test(value) || !Number.isFinite(Date.parse(value)))) throw new Error(`${location}: invalid date-time`);
  }
  if (Array.isArray(value)) {
    if (value.length > (schema.maxItems ?? Infinity)) throw new Error(`${location}: too many items`);
    const ids = new Set<string>();
    value.forEach((item, index) => {
      validateDefinition(item, schema.items, `${location}[${index}]`);
      if (ids.has(item.id)) throw new Error(`${location}[${index}].id: duplicate id`);
      ids.add(item.id);
    });
  } else if (value && typeof value === "object") {
    const record = value as ObjectValue;
    for (const key of schema.required ?? []) if (!(key in record)) throw new Error(`${location}.${key}: required`);
    for (const key of Object.keys(record)) {
      if (!Object.prototype.hasOwnProperty.call(schema.properties ?? {}, key)) throw new Error(`${location}.${key}: unknown field`);
      validateDefinition(record[key], schema.properties[key], `${location}.${key}`);
    }
  }
}

export function mergeInformation(base: ObjectValue, patch: ObjectValue, schema: ObjectValue) {
  validateDefinition(base, schema);
  const partial = structuredClone(schema);
  delete partial.required;
  for (const key of ["schema_version", "generated_at", "source"]) delete partial.properties[key];
  delete partial.properties.product.required;
  for (const key of ["programs", "licenses"]) partial.properties[key].items.required = ["id"];
  validateDefinition(patch, partial, "override");
  const merged: ObjectValue = { ...base, product: { ...base.product, ...patch.product } };
  for (const key of ["programs", "licenses"]) {
    const items = new Map<string, ObjectValue>(base[key].map((item: ObjectValue) => [item.id, { ...item }]));
    for (const item of patch[key] ?? []) items.set(item.id, { ...items.get(item.id), ...item });
    merged[key] = [...items.values()];
  }
  validateDefinition(merged, schema);
  for (const key of ["programs", "licenses"]) merged[key] = merged[key].filter((item: ObjectValue) => !item.hidden);
  return merged;
}

export async function registerInformation(app: FastifyInstance, options: { file: string; override: string; schema: string }) {
  app.get("/api/information", async (_request, reply) => {
    reply.header("Cache-Control", "no-store");
    let phase = "generated";
    try {
      const base = JSON.parse(await boundedRead(options.file));
      phase = "schema";
      const schema = JSON.parse(await boundedRead(options.schema));
      phase = "generated";
      validateDefinition(base, schema);
      phase = "override";
      let patch = {};
      try { patch = JSON.parse(await boundedRead(options.override)); }
      catch (error) { if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error; }
      return mergeInformation(base, patch, schema);
    } catch (error) {
      const missing = (error as NodeJS.ErrnoException).code === "ENOENT";
      const invalid = error instanceof SyntaxError || !(error as NodeJS.ErrnoException).code;
      const status = missing ? 503 : invalid ? 422 : 500;
      const message = missing ? `Information ${phase} file is unavailable` : invalid ? `Invalid Information ${phase}: ${(error as Error).message}` : "Unable to read Information files";
      app.log.warn({ error, phase }, message);
      return reply.code(status).send({ error: message });
    }
  });
}

async function boundedRead(file: string) {
  const text = await readFile(file, "utf8");
  if (Buffer.byteLength(text) > 2 * 1024 * 1024) throw new Error("definition exceeds 2 MiB");
  return text;
}
