  await fs.writeFile(path.join(root, 'docker/supervisord.dev.conf'), '[program:stm]\ncommand="%(ENV_STM_BIN_DIR)s/stm" --config "%(ENV_STM_CONFIG_DIR)s/stm_config.json"\n');
