test('source startup generates at the API state path from workspace, fe and server directories', async t => {
  const { root, fe, options, env, app, override, buildFile } = await fixture(t);
  assert.equal((await app.inject('/api/information')).statusCode, 503);
  const previous = process.cwd();
  try {
    for (const cwd of [root, fe, path.join(fe, 'server')]) {
      process.chdir(cwd);
      assert.equal(await prepareDevelopmentInformation(options, env), true);
      const response = await app.inject('/api/information');
      assert.equal(response.statusCode, 200, response.body);
      const result = response.json();
      assert.equal(result.product.name, 'Development');
      assert.equal(result.product.manufacturer, 'Manual maker');
      assert.equal(result.source, path.join(root, 'docker/supervisord.dev.conf'));
      assert.equal(result.programs.find(program => program.id === 'stm').commit, 'frozen');
      assert.ok(result.programs.some(program => program.id === 'stm/tshark'));
    }
  } finally { process.chdir(previous); }
  assert.equal(await fs.readFile(override, 'utf8'), '{"product":{"manufacturer":"Manual maker"}}');
  assert.equal(await fs.readFile(buildFile, 'utf8'), '{"commit":"immutable-build"}');
  assert.match(await fs.readFile(path.join(fe, 'external-pages/assets/tokens.css'), 'utf8'), /fixture tokens/);
});

test('explicit inventory paths and packaged installations do not regenerate or replace files', async t => {
  const { root, options, env } = await fixture(t);
  await fs.writeFile(options.file, 'keep custom inventory');
  assert.equal(await prepareDevelopmentInformation(options, { ...env, STM_INFORMATION_FILE: options.file }), false);
  assert.equal(await fs.readFile(options.file, 'utf8'), 'keep custom inventory');
  assert.equal(await prepareDevelopmentInformation({ ...options, rootDir: path.join(root, 'packaged/fe') }, env), false);
  assert.equal(await fs.readFile(options.file, 'utf8'), 'keep custom inventory');
});

test('custom Supervisor and binary locations are respected; failed regeneration removes stale data', async t => {
  const { root, options, env, app, override } = await fixture(t);
  const other = path.join(root, 'other-bin');
  await fs.mkdir(other);
  await fs.copyFile(path.join(root, 'be/build/stm'), path.join(other, 'stm'));
  await fs.writeFile(path.join(root, 'docker/custom.conf'), '[program:custom-stm]\ncommand="%(ENV_STM_BIN_DIR)s/stm"\n');
  assert.equal(await prepareDevelopmentInformation(options, { ...env, SUPERVISOR_CONFIG: 'docker/custom.conf', STM_BIN_DIR: other }), true);
  let response = await app.inject('/api/information');
  assert.equal(response.statusCode, 200);
  assert.equal(response.json().programs[0].id, 'custom-stm');
  assert.equal(response.json().programs[0].status, 'ok');
  await assert.rejects(prepareDevelopmentInformation(options, { ...env, SUPERVISOR_CONFIG: 'docker/missing.conf' }));
  response = await app.inject('/api/information');
  assert.equal(response.statusCode, 503);
  assert.equal(await fs.readFile(override, 'utf8'), '{"product":{"manufacturer":"Manual maker"}}');
});

